CREATE OR REPLACE FUNCTION public.refresh_overdue_maintenance(p_organization_id UUID) RETURNS INTEGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE affected INTEGER; BEGIN IF NOT EXISTS (SELECT 1 FROM public.current_user_org_ids() AS org_id WHERE org_id = p_organization_id) THEN RAISE EXCEPTION 'Not authorized'; END IF; UPDATE public.maintenance_schedules AS ms SET status = 'OVERDUE', updated_at = now() FROM public.vehicles AS v WHERE ms.vehicle_id = v.id AND ms.organization_id = p_organization_id AND ms.status = 'SCHEDULED' AND ((ms.due_date IS NOT NULL AND ms.due_date < CURRENT_DATE) OR (ms.due_odometer IS NOT NULL AND v.odometer IS NOT NULL AND v.odometer >= ms.due_odometer) OR (ms.due_engine_hours IS NOT NULL AND v.engine_hours IS NOT NULL AND v.engine_hours >= ms.due_engine_hours)); GET DIAGNOSTICS affected = ROW_COUNT; RETURN affected; END; $$;